    {
      "id": "E02a1d87186038e2d",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O guia de inspeção do HSE apresenta a gestão de mudanças como uma das áreas centrais de intervenção na inspeção de sistemas de segurança de processo voltados à prevenção de perda de contenção.",
          "trechos": [
            "E02a1d87186038e2d:1389:2089"
          ],
          "condicoes": [
            "No contexto do guia de inspeção offshore do HSE para risco de loss of containment"
          ],
          "limites": [
            "Trata-se de orientação regulatória estrangeira, não de requisito brasileiro por si só",
            "O trecho não detalha critérios operacionais específicos da gestão de mudanças"
          ]
        },
        {
          "proposicao": "Segundo o guia, medidas para minimizar risco de perda de contenção devem ser efetivas ao longo do ciclo de vida da instalação e sob condições previsíveis de planta.",
          "trechos": [
            "E02a1d87186038e2d:699:1389"
          ],
          "condicoes": [
            "Aplicável ao escopo do guia de inspeção do HSE sobre instalações offshore"
          ],
          "limites": [
            "Formulação vinculada ao contexto regulatório e de fiscalização do Reino Unido",
            "O trecho não especifica quais medidas concretas são exigidas para cada área de intervenção"
          ]
        },
        {
          "proposicao": "O guia associa a inspeção de perda de contenção a múltiplas áreas integradas, incluindo operação dentro de limites seguros, isolamentos de processo, reintegração após manutenção, monitoramento e revisão, além de gestão de mudanças.",
          "trechos": [
            "E02a1d87186038e2d:1389:2089"
          ],
          "condicoes": [
            "No framework do HSE para inspeção de segurança de processo offshore"
          ],
          "limites": [
            "É uma estrutura de inspeção e não uma descrição exaustiva de procedimento operacional de FPSO",
            "Não deve ser convertida automaticamente em obrigação aplicável no Brasil"
          ]
        }
      ]
    },
    {
